use std::process::Command;
use std::io;

/// Execute a system command and return the output
/// 
/// # Arguments
/// 
/// * `command` - A string slice that holds the command to execute
/// 
/// # Returns
/// 
/// * `Result<String, String>` - Ok with stdout if successful, Err with error message otherwise
pub fn execute_command(command: &str) -> Result<String, String> {
    let mut parts = command.split_whitespace();

    let program = match parts.next() {
        Some(prog) => prog,
        None => return Err("Empty command".to_string()),
    };

    let args: Vec<&str> = parts.collect();

    match Command::new(program).args(&args).output() {
        Ok(output) => {
            if output.status.success() {
                let stdout = String::from_utf8_lossy(&output.stdout);
                Ok(stdout.to_string())
            } else {
                let stderr = String::from_utf8_lossy(&output.stderr);
                Err(format!("Command failed with status {}: {}", output.status, stderr))
            }
        }
        Err(e) => Err(format!("Failed to execute command: {}", e)),
    }
}

/// Execute a system command with input and return both stdout and stderr
/// 
/// # Arguments
/// 
/// * `command` - A string slice that holds the command to execute
/// * `input` - Optional input to provide to the command's stdin
/// 
/// # Returns
/// 
/// * `Result<(String, String), String>` - Ok with (stdout, stderr) if successful, Err with error message otherwise
pub fn execute_command_with_input(command: &str, input: Option<&str>) -> Result<(String, String), String> {
    let mut parts = command.split_whitespace();

    let program = match parts.next() {
        Some(prog) => prog,
        None => return Err("Empty command".to_string()),
    };

    let args: Vec<&str> = parts.collect();

    let mut cmd = Command::new(program);
    cmd.args(&args);

    if let Some(input_str) = input {
        cmd.stdin(std::process::Stdio::piped());
    }

    match cmd.output() {
        Ok(output) => {
            let stdout = String::from_utf8_lossy(&output.stdout).to_string();
            let stderr = String::from_utf8_lossy(&output.stderr).to_string();

            if output.status.success() {
                Ok((stdout, stderr))
            } else {
                Err(format!("Command failed with status {}: {}", output.status, stderr))
            }
        }
        Err(e) => Err(format!("Failed to execute command: {}", e)),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_execute_simple_command() {
        // Test a simple command that should always work
        let result = execute_command("echo hello");
        assert!(result.is_ok());
        assert_eq!(result.unwrap().trim(), "hello");
    }

    #[test]
    fn test_execute_invalid_command() {
        // Test an invalid command
        let result = execute_command("this_command_definitely_does_not_exist");
        assert!(result.is_err());
    }
}
